/**
 * A thin line that divides content (`design/components/separator.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/separator.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { claimSlot, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/separator.module.css'

export type SeparatorOrientation = NonNullable<SeparatorProps['orientation']>

export interface SeparatorProps {
  /**
   * The divider's text, rendered as given; the caller chooses the case, as in "OR".
   */
  label?: string
  /**
   * Vertical needs a sized flex row to stretch inside.
   */
  orientation?: 'horizontal' | 'vertical'
}

/** A thin line that divides content. */
export default function Separator(given: SeparatorProps): JSX.Element {
  const props = mergeProps(
    { orientation: 'horizontal' } as Defaults<SeparatorProps, 'orientation'>,
    claimSlot(given),
  )
  return (
    <>
      {props.label !== undefined ? (
        <div class={styles.labelled} data-orientation="horizontal" data-member="separator">
          {/* rule */}
          <span class={styles.rule} />
          {/* label */}
          <span class={styles.label}>{props.label}</span>
          {/* rule */}
          <span class={styles.rule} />
        </div>
      ) : (
        <div
          class={styles.separator}
          data-orientation={props.orientation}
          aria-hidden="true"
          data-member="separator"
        />
      )}
    </>
  )
}
